69	int ipv6_from_netdev_ns_for_pod_check(const struct __ctx_buff *ctx)
70	{
71		void *data;
72		void *data_end;
73		__u32 *status_code;
74		struct ethhdr *l2;
75		struct ipv6hdr *l3;
76		struct icmp6hdr *l4;
77		void *payload;
78	
79		test_init();
80	
81		data = (void *)(long)ctx->data;
82		data_end = (void *)(long)ctx->data_end;
83	
84		if (data + sizeof(*status_code) > data_end)
85			test_fatal("status code out of bounds");
86	
87		status_code = data;
88		assert(*status_code == CTX_ACT_REDIRECT);
89	
90		l2 = data + sizeof(*status_code);
91	
92		if ((void *)l2 + sizeof(struct ethhdr) > data_end)
93			test_fatal("l2 out of bounds");
94	
95		if (l2->h_proto != bpf_htons(ETH_P_IPV6))
96			test_fatal("l2 proto hasn't been set to ETH_P_IP");
97	
98		union macaddr node_mac = THIS_INTERFACE_MAC;
99	
100		if (memcmp(l2->h_source, (__u8 *)&node_mac.addr, ETH_ALEN) != 0)
101			test_fatal("src mac hasn't been set to node mac");
102	
103		if (memcmp(l2->h_dest, (__u8 *)mac_one, ETH_ALEN) != 0)
104			test_fatal("dest mac hasn't been set to source mac");
105	
106		l3 = (void *)l2 + sizeof(struct ethhdr);
107	
108		if ((void *)l3 + sizeof(struct ipv6hdr) > data_end)
109			test_fatal("l3 out of bounds");
110	
111		union v6addr router_ip = CONFIG(router_ipv6);
112	
113		if (memcmp((__u8 *)&l3->saddr, (__u8 *)&router_ip, 16) != 0)
114			test_fatal("src IP hasn't been set to router IP");
115	
116		if (memcmp((__u8 *)&l3->daddr, (__u8 *)v6_pod_one, 16) != 0)
117			test_fatal("dest IP hasn't been set to source IP");
118	
119		l4 = (void *)l3 + sizeof(struct ipv6hdr);
120	
121		if ((void *)l4 + sizeof(struct icmp6hdr) > data_end)
122			test_fatal("l4 out of bounds");
123	
124		if (l4->icmp6_type != ICMP6_NA_MSG_TYPE)
125			test_fatal("icmp6 type hasn't been set to ICMP6_NA_MSG_TYPE");
126	
127		payload = (void *)l4 + sizeof(struct icmp6hdr);
128		if ((void *)payload + 24 > data_end)
129			test_fatal("payload out of bounds");
130	
131		void *target = payload;
132	
133		if (memcmp(target, (__u8 *)v6_pod_three, 16) != 0)
134			test_fatal("icmp6 payload target hasn't been set properly");
135	
136		void *target_lladdr = payload + 16 + 2;
137	
138		if (memcmp(target_lladdr, (__u8 *)&node_mac.addr, ETH_ALEN) != 0)
139			test_fatal("icmp6 payload target_lladdr hasn't been set properly");
140	
141		test_finish();
142	}
