91	/*
92	 * icmp6_ndisc_adv_addopt
93	 * @ctx:	socket buffer
94	 *
95	 * Grow the packet by ICMP6_ND_OPT_LEN bytes to make room for a target
96	 * link-layer address option in cases where the incoming Neighbour
97	 * Solicitation did not carry a source link-layer address option (and hence
98	 * no trailing option is present). The newly added bytes are zeroed so that
99	 * the checksum stays additive when the caller reads the "old" options.
100	 */
101	static __always_inline
102	int icmp6_ndisc_adv_addopt(struct __ctx_buff *ctx)
103	{
104		struct ipv6hdr *ip6;
105		void *data, *data_end;
106		__u64 *opt;
107	
108		if (ctx_change_tail(ctx, (__u32)(ctx_full_len(ctx) + ICMP6_ND_OPT_LEN), 0) < 0)
109			return DROP_INVALID;
110	
111		if (!revalidate_data(ctx, &data, &data_end, &ip6))
112			return DROP_INVALID;
113	
114		ip6->payload_len = bpf_htons(bpf_ntohs(ip6->payload_len)
115							+ ICMP6_ND_OPT_LEN);
116	
117		/* 0 options pkt to make sure csum is additive when read old_opts */
118		opt = (__u64 *)((void *)(ip6 + 1) + sizeof(struct icmp6hdr)
119							+ sizeof(union v6addr));
120		if ((void *)(opt + 1) > data_end)
121			return DROP_INVALID;
122		*opt = 0x0ULL;
123	
124		return 0;
125	}
